import memfs from 'memfs'
import type { FileSystem, Telemetry } from '@servicenow/sdk-build-core'
import { Orchestrator, Project, ProjectFactory } from '../../src'

describe('Orchestrator.applyTemplate Test Suite', () => {
    let telemetry: Telemetry

    beforeEach(() => {
        jest.clearAllMocks()
        telemetry = {
            sendEvent: jest.fn(),
            error: jest.fn(),
            startTimerEvent: jest.fn().mockReturnValue({
                end: jest.fn().mockReturnValue({ name: 'init.apply-template', data: {} }),
            }),
        } as unknown as Telemetry
    })

    test('apply a template to an existing project', async () => {
        const vol = new memfs.Volume()
        const fs = memfs.createFsFromVolume(vol)

        const factory = new ProjectFactory(fs as FileSystem, telemetry)

        const project = factory.createProject('/', {
            name: 'test',
            packageName: '@servicenow/test',
            description: 'description',
            scope: 'x_test',
            sdkVersion: '4.0.0',
            projectVersion: '1.0.0',
        })

        expect(project).toBeDefined()

        const fsJson = Object.keys(vol.toJSON())
        expect(fsJson.includes('/now.config.json')).toBe(true)
        expect(fsJson.includes('/package.json')).toBe(true)
        expect(fsJson.includes('/src/fluent/index.now.ts')).toBe(true)
        expect(fsJson.includes('/.gitignore')).toBe(true)
        expect(fsJson.includes('/.eslintrc')).toBe(true)
        expect(fsJson.includes('/.vscode/extensions.json')).toBe(true)

        expect(fsJson.includes('/src/fluent/example.now.ts')).toBe(false)
        expect(fsJson.includes('/src/server/tsconfig.json')).toBe(false)
        expect(fsJson.includes('/src/server/script.ts')).toBe(false)

        const orchestrator = new Orchestrator(project)
        const appliedFiles = await orchestrator.applyTemplate('typescript.basic')
        expect(appliedFiles).toBeDefined()
        expect(appliedFiles.length).toBeGreaterThan(0)

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('init.apply-template')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()

        const applyJson = Object.keys(vol.toJSON())

        expect(applyJson.includes('/src/fluent/example.now.ts')).toBe(true)
        expect(applyJson.includes('/src/server/tsconfig.json')).toBe(true)
        expect(applyJson.includes('/src/server/script.ts')).toBe(true)
    })

    test('apply a template file collisions throws error', async () => {
        const vol = new memfs.Volume()
        const fs = memfs.createFsFromVolume(vol)

        const factory = new ProjectFactory(fs as FileSystem)

        factory.createProject('/', {
            name: 'test',
            packageName: '@servicenow/test',
            description: 'description',
            scope: 'x_test',
            sdkVersion: '4.0.0',
            projectVersion: '1.0.0',
            templateId: 'typescript.basic',
        })

        const fsJson = Object.keys(vol.toJSON())
        expect(fsJson.includes('/now.config.json')).toBe(true)
        expect(fsJson.includes('/package.json')).toBe(true)
        expect(fsJson.includes('/src/fluent/index.now.ts')).toBe(true)
        expect(fsJson.includes('/.gitignore')).toBe(true)
        expect(fsJson.includes('/.eslintrc')).toBe(true)
        expect(fsJson.includes('/.vscode/extensions.json')).toBe(true)
        expect(fsJson.includes('/src/fluent/example.now.ts')).toBe(true)
        expect(fsJson.includes('/src/server/tsconfig.json')).toBe(true)

        const existingJson = vol.toJSON()
        expect(Object.keys(existingJson).includes('/src/server/tsconfig.json')).toBe(true)

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger: console,
            rootDir: '/',
            telemetryClient: telemetry,
        })

        const orchestrator = new Orchestrator(project)
        await expect(orchestrator.applyTemplate('typescript.basic')).rejects.toThrow(
            'Collision detected with template file that is not mergable: src/fluent/example.now.ts'
        )

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('init.apply-template')
        expect(telemetry.sendEvent).not.toHaveBeenCalled()
        expect(telemetry.error).toHaveBeenCalledWith(
            'init.apply-template',
            expect.any(Error),
            expect.objectContaining({
                existing: true,
                templateId: 'typescript.basic',
            })
        )
    })

    test('apply a template to an existing project', async () => {
        const vol = new memfs.Volume()
        const fs = memfs.createFsFromVolume(vol)

        const factory = new ProjectFactory(fs as FileSystem, telemetry)

        const project = factory.createProject('/', {
            name: 'test',
            packageName: '@servicenow/test',
            description: 'description',
            scope: 'x_test',
            sdkVersion: '4.0.0',
            projectVersion: '1.0.0',
        })

        const orchestrator = new Orchestrator(project)
        const appliedFiles = await orchestrator.applyTemplate('partial.typescript.react')
        expect(appliedFiles).toBeDefined()
        expect(appliedFiles.length).toBeGreaterThan(0)

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('init.apply-template')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()

        const applyJson = Object.keys(vol.toJSON())

        expect(applyJson).toContain('/src/fluent/ui-pages/incident-manager.now.ts')
        expect(applyJson).toContain('/src/client/app.css')
        expect(applyJson).toContain('/src/client/app.tsx')
        expect(applyJson).toContain('/src/client/main.tsx')
        expect(applyJson).toContain('/src/client/index.html')
    })
})
